<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Http\RedirectResponse;use Illuminate\View\View;use Illuminate\Support\Facades\Hash;
class AdminUserController extends Controller {public function index():View{return view('admin.users.index',['users'=>User::latest()->paginate(10)]);}public function create():View{return view('admin.users.form',['user'=>new User,'mode'=>'create']);}public function store(Request $r):RedirectResponse{$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','role'=>'required|in:admin,doctor,nurse','password'=>'required|min:8|confirmed']);User::create(['name'=>$d['name'],'email'=>$d['email'],'role'=>$d['role'],'password'=>$d['password'],'is_active'=>$r->boolean('is_active')]);return redirect()->route('admin.users.index')->with('success','Usuario creado.');}public function edit(User $user):View{return view('admin.users.form',['user'=>$user,'mode'=>'edit']);}public function update(Request $r,User $user):RedirectResponse{$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email,'.$user->id,'role'=>'required|in:admin,doctor,nurse','password'=>'nullable|min:8|confirmed']);$user->fill(['name'=>$d['name'],'email'=>$d['email'],'role'=>$d['role'],'is_active'=>$r->boolean('is_active')]);if(!empty($d['password']))$user->password=Hash::make($d['password']);$user->save();return redirect()->route('admin.users.index')->with('success','Usuario actualizado.');}public function destroy(User $user):RedirectResponse{abort_if($user->id===auth()->id(),422,'No puedes eliminar tu propia cuenta.');$user->delete();return back()->with('success','Usuario eliminado.');}public function show(User $user):View{return view('admin.users.show',['user'=>$user]);}}
